"use strict";(globalThis.webpackChunksummerz||=[]).push([[876241],{217941(e,n,s){s.r(n),s.d(n,{default:()=>c,metadata:()=>i});var i=s(338044),t=s(474848),r=s(28453);const o={slug:"2004/06/19",title:"Lonely Hearts Club",date:new Date("2004-06-19T23:00:00.000Z"),authors:"summerz",tags:["my life in Sydney"]},l={authorsImageUrls:[void 0]};function a(e){const n={li:"li",ol:"ol",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.p,{children:"\uc8fc\ub9d0\uc774\uc9c0\ub9cc, \uc544\uce68\ubd80\ud130 \uc6c0\uc9c1\uc600\ub2e4. Jeffrey\uac00 \uac00\ub974\uccd0\uc900 Bankstown\uc758 Dick Smith\ub85c \uac14\ub2e4, \ub098\uc758 \ud578\ub4dc\ud3f0\uc744 \uc704\ud558\uc5ec (\uc5ec\uae30\uc11c\ub294 \ud578\ub4dc\ud3f0\uc744 \uadf8\ub0e5 mobile \uc774\ub77c\uace0 \ubd80\ub978\ub2e4.). \uc774\uac83\uc800\uac83 \ubcf4\ub2e4\uac00 \uc810\uc6d0\uc5d0\uac8c \ubb3c\uc5b4\ubd24\ub294\ub370 \uc5ed\uc2dc \uc544\ubb34\ub3c4 \ubab0\ub790\ub2e4 - \ud55c\uad6d\uc73c\ub85c sms\ub97c \ubcf4\ub0bc \uc218 \uc788\ub294\uc9c0. \uac00\ub294 \uacf3\ub9c8\ub2e4 \ubb3c\uc5b4\ubd24\ub294\ub370 - \uadf8\ub9ac\uace0 \uc5b4\ucc0c\ubcf4\uba74 \ubcc4\ub85c \uc911\uc694\ud55c \uae30\ub2a5\ub3c4 \uc544\ub2d0 \uac83 \uac19\uc740\ub370, \uc194\uc9c1\ud788 \uc5ec\uae30\uc11c \ud578\ub4dc\ud3f0\uc744 \uc0ac\ub294 \uc0ac\ub78c \uc911\uc5d0 \uc678\uad6d\uc73c\ub85c sms\ub97c \ubcf4\ub0b4\ub294 \uc0ac\ub78c\uc774 \uc5bc\ub9c8\ub098 \ub420 \uac83\uc774\uba70, \uadf8\uac83\ub3c4 (CDMA \ubc29\uc2dd\uc744 \ucc44\ud0dd\ud55c) \ud55c\uad6d\uacfc sms\uac00 \uc804\uc1a1 \uac00\ub2a5\ud55c\uc9c0 \uc544\ub294 \uc0ac\ub78c\uc774 \uc5bc\ub9c8\ub098 \ub420 \uac83\uc778\uac00. \uc624\ub298 \ubfd0\ub9cc \uc544\ub2c8\ub77c \uc774\uc81c\uae4c\uc9c0 \uac14\ub358 \ubaa8\ub4e0 \uc810\ud3ec\uc5d0\uc11c \ub2e4 \ubaa8\ub978\ub2e4\ub294 \ub300\ub2f5\uc744 \ub4e4\uc5b4\uc11c \uc774\uc820 \uadf8\ub0e5 \uadf8\ub7f0\uac00\ubcf4\ub2e4 \ud55c\ub2e4. \uc810\uc6d0\uc5d0\uac8c \uadf8 \uae30\ub2a5\uc774 \uc788\ub290\ub0d0\uace0 \ubb3c\uc5b4\ubcf4\ub2e4\uac00 \uadf8\ub0e5 \uc0c1\uad00\uc5c6\uc73c\ub2c8 \uc2fc \uac78\ub85c \uc0ac\ub294 \uac8c \uc5b4\ub5a0\ub0d0\uace0 \ubb3c\uc5b4\ubd24\ub354\ub2c8, international sms (..\ub77c\uace0 OPTUS\ucabd\uc5d4 \uc801\ud600\uc788\uae34 \ud558\ub354\ub77c) \ub97c \ubaa8\ub974\ub294 \uadf8 \uc810\uc6d0, \uc624\ud788\ub824 \uadf8\uac8c \ubd88\ud655\uc2e4\ud558\uba74 \ubcc4\ub85c \uad8c\ud558\uace0 \uc2f6\uc9c0 \uc54a\ub2e4\uace0 \ub2f9\ub2f9\ud788 \ub9d0\ud55c\ub2e4. \uadf8\ub7ec\uc790\uace0 \ud558\uace0 \ub9d0\uc558\ub2e4. internet cafe\uc5d0 \uac00\uc11c \uc9c1\uc811 \ucc3e\uc544\ubcf4\ub294 \uac8c \ub098\uc744 \uac83 \uac19\ub2e4."}),"\n",(0,t.jsx)(n.p,{children:"\ucc38\uace0\ub85c, \ud604\uc7ac \ud638\uc8fc\uc5d0\uc11c\ub294 OPTUS\uc640 Telstra\uac00 \uac00\uc7a5 \uc798 \ub098\uac00\ub294 \ubaa8\ubc14\uc77c \uc11c\ube44\uc2a4 \ud68c\uc0ac(\uc778 \ub4ef \ud558)\ub2e4. \uc6b0\ub9ac\ub098\ub77c\ub85c \uce58\uba74 SK\uc640 KTF \uc815\ub3c4 \ub418\uaca0\uc9c0. \uadf8 \ubc16\uc5d0 Vodafone, Orange, 3C(\ub9de\ub098?), Virgin \ub4f1\uc774 \uc788\ub2e4. John\uacfc Tessie, \uadf8\ub9ac\uace0 \ud578\ub4dc\ud3f0\uc5d0 \ub300\ud574\uc11c\ub294 \ub300\ub2e8\ud55c \uc9c0\uc2dd\uc744 \uc790\ub791(?)\ud558\ub294 Grace\uc758 \ub9d0\uc5d0 \uc758\ud558\uba74 OPTUS, Telstra\uac00 \uac00\uc7a5 \uc548\uc815\uc801\uc774\uace0, Vodafone\uae4c\uc9c0\ub294 \uad1c\ucc2e\uc740\ub370 \ub2e4\ub978 \uac74 \ube44\ucd94\ucc9c\uc774\ub77c\uace0 \ud55c\ub2e4. \ub9c8\uce58 \ucc2c\ubc25\uc2e0\uc138, \ucc9c\ub355\uafb8\ub7ec\uae30 \uc6b0\ub9ac\ub098\ub77c\uc758 LG\ud154\ub808\ucf64\uc744 \ubcf4\ub294 \ub4ef;;;"}),"\n",(0,t.jsx)(n.p,{children:"\ub098\uac04 \uae38\uc5d0 John\uc740 Hungry Jack's\uc5d0 \uac00\uc11c \ud584\ubc84\uac70\ub97c \uc0ac\uc654\ub2e4. \uc194\uc9c1\ud788 Hungry Jack's\uc758 \ud584\ubc84\uac70\ub294 \ucc98\uc74c \uba39\uc5b4\ubd24\ub294\ub370, \uc5b4\ub77c- \ud3ec\uc7a5\uc9c0\uc5d0\uc11c\ubd80\ud130 \uc640\ud37c Woffer\ub77c\uace0 \uc801\ud600\uc788\ub294 \uac8c \uc544\ub2cc\uac00. \uba39\uc5b4\ubcf4\ub2c8 BK (Burger King)\uc758 \uc640\ud37c\ub791 \ub9db\uc774 \ub611\uac19\ub2e4. \ub54c\ub9c8\uce68 \ubc15\ud559\ub2e4\uc2dd\ud55c John\uc758 \uc124\uba85\uc774 \uc774\uc5b4\uc84c\ub2e4. BK\ub97c \ud638\uc8fc\uc5d0 \ucc98\uc74c \ub4e4\uc5ec\uc628 \uc0ac\ub78c\uc774 Jack (Cowin ?) \uc774\ub77c\ub294 \uc0ac\ub78c\uc774\uc5c8\ub2e8\ub2e4. \uadf8\ub7f0\ub370, \uadf8\uac00 \ub4e4\uc5ec\uc62c \ub54c\ub294 \uc0c1\ud45c\uad8c(?) \ubb38\uc81c \ub54c\ubb38\uc5d0 Hungry Jack's\ub77c\uace0 \uc774\ub984 \ubd99\uc5ec \ub4e4\uc5ec\uc654\ub294\ub370, BK\uac00 \uadf8 \ud6c4\uc5d0 \ub2e4\uc2dc BK \uace0\uc720 \uc774\ub984\uc73c\ub85c \ub4e4\uc5b4\uc640\uc11c \ud638\uc8fc\uc5d0\ub294 \ub450\uac00\uc9c0 BK - \uc989, \uc6d0\ub798 BK\uc640 Hungry Jack's \uc774\ub807\uac8c 2\uac00\uc9c0\uac00 \uc788\ub2e4\uace0 \ud55c\ub2e4. (\uadf8\ub807\ub2e4\uba74 \ud638\uc8fc \ubfd0 \uc544\ub2c8\ub77c \ub2e4\ub978 \uacf3\ub3c4 \ub9c8\ucc2c\uac00\uc9c0\uac00 \ub418\uaca0\uc9c0.) \ud760... \ubbff\uac70\ub098 \ub9d0\uac70\ub098. (\uc774\uac70 \uc0ac\uc2e4\uc778\uac00\uc694?)"}),"\n",(0,t.jsx)(n.p,{children:"\uc0b4\uc9dd \ucd94\uc6cc\uc11c \uc870\ub07c\ub97c \uc785\uace0 \uc788\uc73c\ub2c8 \ub418\ub824 \ub728\ub73b\ud574\uc838\uc11c \uc810\uc2ec \uba39\uace0 \uc194\uc194 \uc7a0\uc774 \uc654\ub2e4. \uc7a0\uae50 \uc878\ub2e4\uac00 \uc815\uc2e0 \ucc28\ub9ac\uace0, \uc55e\uc73c\ub85c \ubb54\uac00 \ud574\uc57c\ud560 \uac83\ub4e4, \uc815\ub9ac\ud560 \uac83\ub4e4\uc744 \ucc28\ub840\ub85c \uc815\ub9ac\ud558\uace0 \ub098\ub2c8,"}),"\n",(0,t.jsx)(n.p,{children:"\ub450\ub450\ub465\ub465."}),"\n",(0,t.jsx)(n.p,{children:"\ub4dc\ub514\uc5b4 \ub54c\uac00 \uc654\ub2e4. Saturday Night Fever. \uadf8\ub0e5 \uc637 \uc785\uace0 \uc788\ub358 \ucc44\ub85c \ub098\uac00\ub294\ub370, \uc5b4\ub78f. Missy\ub294 \ubbf8\ub2c8 \uc2a4\ucee4\ud2b8\ub97c \uc785\uace0, Tessie\ub294 \ud654\uc7a5\ub3c4 \ud558\uace0, \uc5ed\uc2dc John\uc740 \uac70\uc758 \ud3c9\uc0c1\ubcf5 \ucc28\ub9bc. \uc7a0\ubc14 \ud558\ub098 \uac78\uce58\uace0 \ubaa9\uc801\uc9c0\ub85c \ud5a5\ud588\ub2e4. \ubb34\uc2a8 wood\uc778\ub370 \uae4c\uba39\uc5c8\ub2e4 (\uc544\uc544- \uae38\uce58\uae38\uce58\uae38\uce58. Burwood\uc600\ub098?). \uac00\ub294 \uae38\uc5d0 Grace\ub97c \ud0dc\uc6b0\uace0, \ub3c4\ucc29\ud558\ub2c8 Bob\uacfc Viki (\ub458\uc740 \ubd80\ubd80), \uadf8\ub9ac\uace0 Virgie\uac00 \uc640 \uc788\uc5c8\ub2e4 (Virgie\uc640 Don\uc774 \ubd80\ubd80). 2\uce35\uc73c\ub85c \uc62c\ub77c\uac00\uc11c (\ub304\uc2f1\ud640\uc774 2\uce35) \uc785\uc7a5\ub8cc\uac00 $15\uc5ec\uc11c \uc11c\ub85c \ub098\ub294 \uc548\ub4e4\uc5b4\uac00\ub124 \ub4e4\uc5b4\uac00\ub124 \ucda4\uc744 \ubabb\ucd94\ub124 \uc548\ucd94\ub124 \ucdb0\uc57c\ud558\ub124 \uadf8\ub7ec\uace0 \uc788\ub2e4\uac00 \uc548 \ub4e4\uc5b4\uac08 \uc0ac\ub78c, \ub4e4\uc5b4\uac08 \uc0ac\ub78c \uc815\ud588\ub294\ub370 \uac70\uae30 \uae30\ub3c4\uac00 \ub098\ub294 \ubcf5\uc7a5\uc0c1\ud0dc\uac00 \ubd88\ub7c9\ud574\uc11c \ubabb\ub4e4\uc5b4\uac04\ub2e8\ub2e4. -o-"}),"\n",(0,t.jsx)(n.p,{children:"\ud55c\ub9c8\ub514\ub85c \uadf8 \uacf3\uc740 '\uc9dd\uc783\uc740 \uc678\ub85c\uc6b4 \uc678\uae30\ub7ec\uae30 \uc9dd \ucc3e\ub294...', Lonely Hearts Club \uc774\uc5c8\ub358 \uac8c\ub2e4. \uac70\uae30 \uc774\ub984\ub3c4 Singles Sydney \uc600\ub098? \uc554\ud2bc. \uc591\ubcf5 (\ube44\uc2b7\ud558\uac8c\ub77c\ub3c4, \uc801\uc5b4\ub3c4 \ud3c9\ubc94\ud55c \uba74\ubc14\uc9c0\ub77c\ub3c4) \uc785\uc5b4\uc57c \ud558\uace0, \uc2e0\ubc1c\ub3c4 \uad6c\ub450\ub97c \uc2e0\uc5b4\uc57c \ud558\ub294\ub370, \ub098\ub294 \uadf8\ub0e5 \ud391\ud37c\uc9d0\ud55c \ubc14\uc9c0\uc5d0 (\ub9ac\ud2b8\uba38\uc2a4\ub2d8- \ub9ac\ud2b8\uba38\uc2a4\ub2d8\uc774 \uc900 \uadf8 \ubc14\uc9c0\uc608\uc694;; \uc774\ub978\ubc14 \uac74\ube75\ubc14\uc9c0) \uc6b4\ub3d9\ud654 \uc2e0\uace0 \uac14\uc73c\ub2c8 \ub2f9\uc5f0\ud788 \uc548\ub418\uc9c0. \ub098\uc774\uac00 \uc880 \ub4e0 \uc0ac\ub78c\ub4e4\uc740 \uadf8\ub798\ub3c4 \ub4e4\uc5b4\uac00\ub358\ub370, \ub098\ub294 \uc5bc\uad74\uae4c\uc9c0 \uc5b4\ub824\ubcf4\uc774\ub2c8 (\uc218\uc90d;; ) \ub354\uc6b1 \uc548\ub41c\uac8c\uc9c0 (...\ub77c\uace0 \uc0dd\uac01\ud55c\ub2e4. -_-v)."}),"\n",(0,t.jsx)(n.p,{children:"\uac00\uc790\uace0 \uc120\ub3d9\ud588\ub358 Grace\uc640 Virgie\ub294 \ub2f9\uc5f0\ud788 \uc785\uc7a5, \uc637 \ucc28\ub824\uc785\uace0 \uc628 Missy\ub294 \uc5bc\ub5a8\uacb0\uc5d0 \uc785\uc7a5, \uadf8\ub7f0 Missy\ub97c \ubcf4\ud638\ud558\uae30 \uc704\ud558\uc5ec Tessie\ub3c4 \ub3d9\ubc18 \uc785\uc7a5, Bob\uacfc Viki, John, \ub098\ub294 \ub4e4\uc5b4\uac00\uc9c0 \uc54a\uace0 1\uce35\uc5d0 \uc549\uc544\uc11c \ub9e5\uc8fc\ub97c \uba39\uc5c8\ub2e4. \uba39\uace0 \uc788\uc73c\ub2c8 \ub9c8\uc624\uc774\uc871\uc774 \ub098\uc640\uc11c \ud37c\ud3ec\uba3c\uc2a4\ub97c \ud55c\ub2e4. \uadf8... \uace8\ubc18\ucda4-_-\ub3c4 \ucd94\uace0, \ubd88\uc448-\ub3c4 \ud558\uace0, \uad00\uac1d\ub4e4 \ubd88\ub7ec\ub4e4\uc5ec\uc640\uc11c \ud568\uaed8 \uace8\ubc18\ucda4\ub3c4 \ucd94\uace0;;; \uce74\uba54\ub77c\ub97c \uac00\uc838\uac08 \uac78 \uadf8\ub7ac\ub098?"}),"\n",(0,t.jsx)(n.p,{children:"\uc5b4\uca0c\ub4e0 \uc88b\uc740 \uacbd\ud5d8. \uc0ac\uc2e4 Missy\uc640 \ub098\ub294 John\uc774\ub098 Tessie \uc138\ub300\uc640 \uc544\uc8fc \uc798 \uc5b4\uc6b8\ub9ac\ub294 \uac74 \uc880 \ubb34\ub9ac\ub77c\uace0 \uc0dd\uac01\ud55c\ub2e4. (\ud760. \uadf8\ub807\ub2e4\uace0 Missy\uc640 \ub0b4\uac00 \ub3d9\uc138\ub300\ub0d0. \uadf8\uac83\ub3c4 \uc0ac\uc2e4 \uc560\ub9e4\ud558\uc9c0. \ub531 10\uc0b4 \ucc28\uc774\ub2e4. -o-) \uc0ac\uc2e4 \uc801\uc5b4\ub3c4 \uc774\ubaa8, \uc0bc\ucd0c \ubed8\uc774\uace0 \uc798 \ud558\uba74 \uc5b4\uba38\ub2c8, \uc544\ubc84\uc9c0 \ubed8 \ub418\ub2c8\uae4c. (\uac70\uae30\uc11c\ub3c4 John\uc774 \ub098\ubcf4\uace0 '\uc548\ub4e4\uc5b4\uac00\uae38 \uc798\ud588\ub2e4, \ub4e4\uc5b4\uac14\uc73c\uba74 \uc5ec\uc790\uce5c\uad6c\uac00 \uc544\ub2c8\ub77c \uc5b4\uba38\ub2c8\ub97c \uad6c\ud574\uc57c \ud588\uc744 \uac70\ub2e4.'\ub77c\uba70 \uc2ec\uc2ec\ud55c \uc704\ub85c\uc758 \ub9d0\uc744 \uc804\ud560 \uc815\ub3c4\uc600\uc73c\ub2c8;;; )"}),"\n",(0,t.jsx)(n.p,{children:"\ub3cc\uc544\uc624\ub294 \uae38\uc5d0 Bob\uacfc Viki\uac00 \ucc28\uc548\uc5d0\uc11c \uc2f8\uc6b4 \ubaa8\uc591\uc778\ub370, \ubd80\ubd80\uc2f8\uc6c0 \ud558\ub294 \ubaa8\uc2b5\uc740 \uc5ed\uc2dc \uc11c\uc591\uc774\ub098 \ub3d9\uc591\uc774\ub098 \ube44\uc2b7\ud558\ub2e4 (\ud55c\ucabd\uc774 \ub3d9\uc591\uc778\uc774\uae30 \ub54c\ubb38\uc5d0 \uadf8\ub7f0\uac74\uc9c0\ub3c4; ). \uadf8\uac78 \ubc14\ub77c\ubcf4\uba70 \uc57d\uc62c\ub9ac\uae30\ub3c4 \ud558\uace0, \ub18d\ub2f4\uc73c\ub85c \ub118\uaca8\uc904\ub824\uace0 \ud558\ub294 \uc0ac\ub78c\ub4e4\uc758 \ubaa8\uc2b5\ub3c4 \ube44\uc2b7\ud558\uace0. John\uacfc Tessie\uac00 \ub18d\ub2f4\ubc18, \uc9c4\ub2f4\ubc18\uc73c\ub85c \ud2f1\ud2f1 \uac70\ub9b4 \ub54c\ub3c4 \ube44\uc2b7\ud568\uc744 \ub290\ub080\ub2e4. \ub2e4 \uc88b\uc544\ud558\ub2c8\uae4c \uc2f8\uc6b0\ub294 \uac70\uc9c0, \ubb58. Bob\uacfc Viki, \ub458 \ub2e4 \ub098\ubcf4\uace0 \uacb0\ud63c\ud558\uc9c0 \ub9d0\uace0 \ud63c\uc790 \uc0b4\ub780\ub2e4. \uacb0\ud63c\ud558\uba74 \uc783\ub294 \uac8c \ub9ce\uace0, \uc774\ub807\uac8c \uc2f8\uc6b0\uae30\ub9cc \ud55c\ub2e4\uace0. \ub458\uc774 \uc2f8\uc6b0\ub294 \uc911\uc774\ub77c \uadf8\ub0e5 \uc6c3\uc5b4\ub118\uacbc\uc9c0. (\uadfc\ub370, Viki\uac00 \uc880 \uc2ec\ud558\uac8c \ud654\uac00 \ub098\uae34 \ud588\ub2e4. Bob\uc774 \uc798\ubabb\ud55c \uac74 \uc0ac\uc2e4\uc774\ub2c8\uae4c;;; )"}),"\n",(0,t.jsx)(n.p,{children:"Saturday Night Fever\ub97c \uae30\ub300\ud558\uba70 \uac00\ub294 \ucc28 \uc548\uc5d0\uc11c \ubb38\ub4dd \uc0dd\uac01\ub09c \ub450\uac00\uc9c0."}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"\ub3d9\ubc18\uc790\ub098 \ubcf4\ud638\uc790(?)\uac00 \uc788\ub354\ub77c\ub3c4 \ubc18\ub4dc\uc2dc \uc2e0\ubd84\uc99d\uc744 \ucc59\uaca8\uac00\uc57c\uc9c0. John\uacfc Tessie\uac00 \uad1c\ucc2e\ub2e4\uace0, \uc124\ub9c8 \ub098\uc774 \ub54c\ubb38\uc5d0 \ubabb\ub4e4\uc5b4\uac00\uaca0\ub0d0\uace0 \ud574\uc11c \uc544\ubb34\uac83\ub3c4 \uc548\uac00\uc9c0\uace0 \uac14\uc9c0\ub9cc, \uc0ac\uc2e4 \ub098\uc57c \uadf8 \ub54c\ubb38\uc774 \uc544\ub2c8\uace0\uc11c\ub77c\ub3c4, \ud604\uc9c0\uc778\uc774 \uc544\ub2c8\ub2c8 \ub9cc\uc57d\uc758 \uc0ac\ud0dc\uc5d0 \ub300\ube44\ud574\uc11c\ub77c\ub3c4 \ud56d\uc0c1 \uc2e0\ubd84\uc99d - \ud559\uad50\uc5d0 \ub4e4\uc5b4\uac00\uae30 \uc804\uae4c\uc9c4 \uc5ec\uad8c\uc744 \uaf2d \uac00\uc9c0\uace0 \ub2e4\ub140\uc57c\uaca0\ub2e4\ub294 \uc0dd\uac01\uc744 \ud588\ub2e4."}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"\ubb38\ub4dd \ud1a0\ub860 \ud504\ub85c\uadf8\ub7a8\uc5d0\uc11c \uc5ec\uc131\uc6b4\ub3d9\ud558\ub294 \uc0ac\ub78c\uacfc \ubcf4\uc218\ub2e8\uccb4\ub97c \ub300\ubcc0\ud558\ub294 \uc0ac\ub78c\uc774 \ub098\uc640\uc11c \ud1a0\ub860\ud588\ub358 \uac8c \uc0dd\uac01\uc774 \ub0ac\ub2e4. \uae40\ucca0\uc218\uc640 \uc774\uc601\ud76c\uac00 \uacb0\ud63c\uc744 \ud574\uc11c \uc544\uc774\uac00 \ud0dc\uc5b4\ub098\uba74 \uadf8 \uc544\uc774\uc758 \uc131\uc740 '\uae40\uc774'\uac00 \ub41c\ub2e4\uac70\ub098, \ud639\uc740 \uc131\uc744 \uc544\uc774\uc758 \uc790\uc728\uc5d0 \ub9e1\uae30\ub294 \uac74 \ub9d0\ub3c4 \uc548\ub418\ub294 \ubc1c\uc0c1\uc774\ub77c\uace0 \uc8fc\uc7a5\ud558\ub358 \ubcf4\uc218\ub2e8\uccb4\uce21\uc758 \uc0ac\ub78c\uc758 \ub9d0. \uc0ac\uc2e4 \ubb50 \ud604\uc2e4\uc801\uc73c\ub85c \ubb34\ub9ac\uac00 \uc788\uc744 \uc218\ub3c4 \uc788\uc9c0. \uadf8\ub7ec\uba74\uc11c \uadf8 \ubc18\ub300\ud558\ub294 \uce21 \uc0ac\ub78c\uc758 \uc608 \uc911\uc758 \ud558\ub098\uac00 \uc678\uad6d\uc5d0\uc11c\ub294 \uacb0\ud63c\ud558\uba74 \uc5ec\uc790\uc758 \uc131\uae4c\uc9c0 \ubc14\ub00c\ub294\ub370 \uc6b0\ub9ac\ub294 \uadf8 \uc815\ub3c4\ub294 \uc544\ub2c8\uc9c0 \uc54a\ub290\ub0d0- \ub77c\uace0 \ud588\ub358 \ub9d0."}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"\ucc28 \uc548\uc5d0\uc11c \uba38\ub9ac \uc18d\uc5d0 \ubb38\ub4dd \ub5a0\uc624\ub974\ub294 \uc0dd\uac01\uc740 \uadf8\ub798\ub3c4- \uadf8\ub4e4\uc740 \uacb0\ud63c\ud574\ub3c4 \uc5b8\uc81c\ub098 \uc11c\ub85c \uc774\ub984\uc744 \ubd80\ub978\ub2e4\ub294 \uc0ac\uc2e4\uc774\ub2e4. \uad49\uc7a5\ud788 \uc911\uc694\ud55c \ucc28\uc774\ub2e4. \uc0dd\ud65c \uc18d\uc5d0\uc11c \uc11c\ub85c\uc758 \uc874\uc7ac\uac00 \ub3d9\ub4f1\ud558\uac8c \uc790\ub9ac\uc7a1\uace0 \uc788\ub2e4\ub294 \uac83\uc774\ub2e4. \uc9d1\uc0ac\ub78c, \ub9c8\ub204\ub77c, \uc5ec\ud3b8\ub124, \ub204\uad6c\ub124 \uc5c4\ub9c8\ub85c \ubd88\ub9ac\uba70 \uc790\uc2e0\uc758 \uc0b6\uc744 \ud3ec\uae30\ud558\uae38 \uac15\uc694\ub2f9\ud558\uace0 - \ubc18\ub300\ub85c \ub204\uad6c\ub124 \uc544\ube60, \ubc14\uae65\uc591\ubc18\uc73c\ub85c \ubd88\ub9ac\uba70 \ub3c8\ubc8c\uc5b4\uc624\ub294 \uae30\uacc4\uac00 \ub418\uc5b4\uac00\ub294 \uc6b0\ub9ac\ub124 \ud604\uc2e4\uacfc\ub294 \uc2dc\uc791\uc810\ubd80\ud130\uac00 \ub2e4\ub974\ub2e4\ub294 \uc0dd\uac01\uc774 \uc0c8\uc0bc \ub4e4\uc5c8\ub2e4. \uc608\uc804\uc5d0 \uce5c\uad6c\ub4e4\uacfc \ud6c4\ubc30\ub4e4\uacfc \uc220 \uba39\ub2e4\uac00 \ub9c8\ub204\ub77c\uac00 \ub0ae\ucda4\ub9d0\uc774\ub0d0 \uc544\ub2c8\ub0d0 \uac00\uc9c0\uace0 \uc774\uc57c\uae30\ud558\ub2e4\uac00 \uc870\uae08 \uacfc\uc5f4\ub418\uc5c8\ub358 \uc801\uc774 \uc0dd\uac01\ub09c\ub2e4. \uadf8 \ud6c4\ubc30\ub294 \uc5bc\ub9c8\ub098 \uc815\uaca8\uc6b4 \uc6b0\ub9ac\ub9d0\uc774\ub0d0, \uc790\uae30\ub294 \uacb0\ud63c\ud558\uba74 \ub9c8\ub204\ub77c\ub77c\uace0 \ubd80\ub97c \uac83\uc774\ub77c\uace0 \ud588\uace0, \ub098\ub294 \uadf8\uac74 \ub0ae\ucda4\ub9d0\uc774 \uc544\ub2c8\uaca0\ub290\ub0d0, \ub0b4 \ubc30\uc6b0\uc790\uac00 '\ub9c8\ub204\ub77c'\ub77c\ub294 \ud638\uce6d\uc73c\ub85c \ubd88\ub824\uc9c0\ub294 \uac74 \uc2eb\ub2e4\uace0 \ud588\uc5c8\ub294\ub370, \uc774\ub7f0 \ucc28\uc6d0\uc870\ucc28\ub3c4 \uc544\ub2c8\ub77c\ub294 \uac83. \uc5b4\ub5bb\uac8c \ubd80\ub974\ub0d0\uc758 \ubb38\uc81c\uac00 \uc544\ub2c8\ub77c \uc0c1\ub300\ubc29\uc5d0 \ub300\ud55c \uc778\uc2dd\uc758 \ucc28\uc774\uc5d0\uc11c\ubd80\ud130 \uc624\ub294 \ucc28\uc6d0\uc774 \uc544\ub2d0\uae4c \uc2f6\uc740 \uc0dd\uac01. \ud760... \ubb38\ud654\uc758 \ucc28\uc774\uc778\uc9c0, \uc778\uc2dd\uc758 \ucc28\uc774\uc778\uc9c0\ub294 \uc544\uc9c1 \uc798 \ubaa8\ub974\uaca0\uc9c0\ub9cc. (\uadf8\uac8c \uadf8\uac74\uac00;;;)"}),"\n",(0,t.jsxs)(n.p,{children:["\uadf8\ub798\uc11c \uacb0\ub860\uc740, \ub2e4\uc18c \uc5c9\ub6b1\ud558\uc9c0\ub9cc- ",(0,t.jsx)(n.strong,{children:"\ud638\uc8fc\uc81c \ud3d0\uc9c0\ud558\ub77c!"})," (...\ub77c\uace0 \uc678\uce58\uba70 \uc368\uba38\uc988, \ud638\uc8fc\uc5d0\uc11c \uc8fc\uba39 \ubd88\ub048 \uc950\ub2e4. :p)"]})]})}function c(e={}){const{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(a,{...e})}):a(e)}s.d(n,["assets",0,l,"contentTitle",0,void 0,"frontMatter",0,o,"toc",0,[]])},28453(e,n,s){s.d(n,{R:()=>o,x:()=>l});var i=s(296540);const t={},r=i.createContext(t);function o(e){const n=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function l(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:o(e.components),i.createElement(r.Provider,{value:n},e.children)}},338044(e){e.exports=JSON.parse('{"permalink":"/blog/2004/06/19","source":"@site/blog/2004/06/2004-06-19/index.md","title":"Lonely Hearts Club","description":"\uc8fc\ub9d0\uc774\uc9c0\ub9cc, \uc544\uce68\ubd80\ud130 \uc6c0\uc9c1\uc600\ub2e4. Jeffrey\uac00 \uac00\ub974\uccd0\uc900 Bankstown\uc758 Dick Smith\ub85c \uac14\ub2e4, \ub098\uc758 \ud578\ub4dc\ud3f0\uc744 \uc704\ud558\uc5ec (\uc5ec\uae30\uc11c\ub294 \ud578\ub4dc\ud3f0\uc744 \uadf8\ub0e5 mobile \uc774\ub77c\uace0 \ubd80\ub978\ub2e4.). \uc774\uac83\uc800\uac83 \ubcf4\ub2e4\uac00 \uc810\uc6d0\uc5d0\uac8c \ubb3c\uc5b4\ubd24\ub294\ub370 \uc5ed\uc2dc \uc544\ubb34\ub3c4 \ubab0\ub790\ub2e4 - \ud55c\uad6d\uc73c\ub85c sms\ub97c \ubcf4\ub0bc \uc218 \uc788\ub294\uc9c0. \uac00\ub294 \uacf3\ub9c8\ub2e4 \ubb3c\uc5b4\ubd24\ub294\ub370 - \uadf8\ub9ac\uace0 \uc5b4\ucc0c\ubcf4\uba74 \ubcc4\ub85c \uc911\uc694\ud55c \uae30\ub2a5\ub3c4 \uc544\ub2d0 \uac83 \uac19\uc740\ub370, \uc194\uc9c1\ud788 \uc5ec\uae30\uc11c \ud578\ub4dc\ud3f0\uc744 \uc0ac\ub294 \uc0ac\ub78c \uc911\uc5d0 \uc678\uad6d\uc73c\ub85c sms\ub97c \ubcf4\ub0b4\ub294 \uc0ac\ub78c\uc774 \uc5bc\ub9c8\ub098 \ub420 \uac83\uc774\uba70, \uadf8\uac83\ub3c4 (CDMA \ubc29\uc2dd\uc744 \ucc44\ud0dd\ud55c) \ud55c\uad6d\uacfc sms\uac00 \uc804\uc1a1 \uac00\ub2a5\ud55c\uc9c0 \uc544\ub294 \uc0ac\ub78c\uc774 \uc5bc\ub9c8\ub098 \ub420 \uac83\uc778\uac00. \uc624\ub298 \ubfd0\ub9cc \uc544\ub2c8\ub77c \uc774\uc81c\uae4c\uc9c0 \uac14\ub358 \ubaa8\ub4e0 \uc810\ud3ec\uc5d0\uc11c \ub2e4 \ubaa8\ub978\ub2e4\ub294 \ub300\ub2f5\uc744 \ub4e4\uc5b4\uc11c \uc774\uc820 \uadf8\ub0e5 \uadf8\ub7f0\uac00\ubcf4\ub2e4 \ud55c\ub2e4. \uc810\uc6d0\uc5d0\uac8c \uadf8 \uae30\ub2a5\uc774 \uc788\ub290\ub0d0\uace0 \ubb3c\uc5b4\ubcf4\ub2e4\uac00 \uadf8\ub0e5 \uc0c1\uad00\uc5c6\uc73c\ub2c8 \uc2fc \uac78\ub85c \uc0ac\ub294 \uac8c \uc5b4\ub5a0\ub0d0\uace0 \ubb3c\uc5b4\ubd24\ub354\ub2c8, international sms (..\ub77c\uace0 OPTUS\ucabd\uc5d4 \uc801\ud600\uc788\uae34 \ud558\ub354\ub77c) \ub97c \ubaa8\ub974\ub294 \uadf8 \uc810\uc6d0, \uc624\ud788\ub824 \uadf8\uac8c \ubd88\ud655\uc2e4\ud558\uba74 \ubcc4\ub85c \uad8c\ud558\uace0 \uc2f6\uc9c0 \uc54a\ub2e4\uace0 \ub2f9\ub2f9\ud788 \ub9d0\ud55c\ub2e4. \uadf8\ub7ec\uc790\uace0 \ud558\uace0 \ub9d0\uc558\ub2e4. internet cafe\uc5d0 \uac00\uc11c \uc9c1\uc811 \ucc3e\uc544\ubcf4\ub294 \uac8c \ub098\uc744 \uac83 \uac19\ub2e4.","date":"2004-06-19T23:00:00.000Z","tags":[{"inline":true,"label":"my life in Sydney","permalink":"/blog/tags/my-life-in-sydney"}],"readingTime":4.66,"hasTruncateMarker":true,"authors":[{"name":"summerz","imageURL":"https://github.com/summerz.png","key":"summerz","page":null}],"frontMatter":{"slug":"2004/06/19","title":"Lonely Hearts Club","date":"2004-06-19T23:00:00.000Z","authors":"summerz","tags":["my life in Sydney"]},"unlisted":false,"prevItem":{"title":"\ub2ed\uace0\uae30 \ubc14\ubca0\ud050","permalink":"/blog/2004/06/20"},"nextItem":{"title":"Powerhouse Museum","permalink":"/blog/2004/06/18"}}')}}]);